class Solution { fun minSwaps(grid:Array<IntArray>):Int{val n=grid.size;val zeros=IntArray(n);for(row in 0 until n)for(col in n-1 downTo 0){if(grid[row][col]!=0)break;zeros[row]++};var answer=0;for(i in 0 until n){var row=i;val need=n-1-i;while(row<n&&zeros[row]<need)row++;if(row==n)return -1;answer+=row-i;while(row>i){val temporary=zeros[row];zeros[row]=zeros[row-1];zeros[row-1]=temporary;row--}};return answer} }
